import type { Phase, VocabItem } from "@/lib/types";

// INGLÉS B2 · MÓDULO 9 — Getting There: empaquetar la circunstancia dentro
// de la frase (subordinación no finita) y moverse por el país de verdad.
//
// El B1 ya cerró los cuatro futuros, las temporales sin will y el léxico de
// aeropuerto. Aquí no se reabre nada de eso. Lo que el B2 añade es meter
// DOS cosas en UNA frase: la circunstancia va delante, en -ing o en
// after having, y el hecho principal sigue. El hispanohablante las pone
// al lado («Cuando terminé, me fui») y es correcto — y es exactamente la
// evitación que el B2 cobra en Range.
//
// GRAMÁTICA ANCLA (EGP, no handbook):
//   (a) -ing delante de la principal: Walking home, I realised…
//   (b) after having/being + -ed y preposición + -ing
//   (c) rather than + no finita · as if / as though + finita
//   (d) there had been — CERO apariciones en todo el B1
//   (e) relativa de frase entera, evaluativa: …, which was a relief
//   (f) preposición al final de la relativa: the flat I told you about
// El participio en -ed delante (Told to wait, she sat) es C1: se lee, no
// se produce, no entra al SRS.
//
// PERICIA: empaquetar. Campo: TRAVEL B2 (green travel, traffic control,
// entering/leaving a country) y PLACES (sat nav, World Heritage, motorways
// & airports, protecting open spaces, flora and fauna).
// GÉNERO: la propuesta (proposal) — uno de los cuatro tipos del Reading 1.
// EXAM LAB (L10): Reading Part 3 — postura del autor, y un texto PUEDE
// ser la respuesta más de una vez.
//
// ELENCO: Valeria, Amy, Ben, Nora. Gwen Pryce guía en St Elen's Priory
// (Gales). Un fin de semana fuera de Londres es un viaje, no una mudanza.
//
// RECICLADO sin redeclarar: ena2m6luggage, ena2m6thecoach, ena2m6passport,
// ena2m6platformfour, ena2m6atrafficjam, ena2m6assoonas, enb1m9cancelled,
// enb1m9bordercontrol, enb1m9connection, enb1m9replacementbus, enb1m9adelay,
// enb1m9whichtexttellsyou, enb1m9samewordwrongtext, enb1m9readthequestionsfirst,
// enb1m9bythetime, enb1m9aslongas, enb1m2endup, enb1m2otherwise, enb1m1although,
// enb1m1despite, enb1m1therefore, enb1m1unless, enb1m4ontheotherhand,
// enb1m4skimthetext, enb1m4factoropinion, ena2m12thepurposeofthetext,
// enb1m3couldyoutellme, enb1m3askedmewhereitwas, enb1m11withoutasking,
// enb1m11inorderto, enb1m2dueto.

